head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[inputCalendar > E > onmonthselect]<br/>팝업 달력에서 월의 선택을 변경했을때 발생합니다.",
    "validation" : [
        "팝업 달력에서 월의 선택을 변경했을때 발생합니다.",        
        "pickerType=selectbox 이면 calendarValueType=year 가 아닐때 onmonthselect 이벤트가 발생합니다.",
        "info 파라미터로 선택이 변경된 월의 정보가 객체로 전달됩니다.",
        "info.oldValue 파라미터로 변경 전에 선택되어 있던 월의 값을 갖습니다.",
        "pickerType=selectbox 이면 info.oldValue 파라미터로 1~12 사이의 숫자값을 갖습니다.",
        "info.newValue 파라미터로 변경 후에 선택된 월의 값을 갖습니다.",
        "pickerType=selectbox 이면 info.newValue 파라미터로 1~12 사이의 숫자값을 갖습니다.",
        "팝업 달력에서 '이전달', '이후달', '이전연월', '다음연월' 버튼 클릭으로 onmonthselect 이벤트가 발생하지 않습니다.",
        "팝업 달력에서 날짜를 클릭하거나 '확인' 버튼을 클릭하여 선택일이 컴포넌트에 반영될때는 onmonthselect 이벤트가 발생하지 않습니다."
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let eList = $c.gcm.createEList(["onmonthselect"]);

    // comp 생성 함수 호출
   $c.gcm.createBasicInputCalendar('', eList);
}



scwin.target1_onmonthselect = function (info) {    
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onmonthselect 이벤트 발생=====");
    wf_body_bottom.getObj("scwin").setReturnValue("info : " + info);
    wf_body_bottom.getObj("scwin").setReturnValue("info.oldValue : " + info.oldValue);
    wf_body_bottom.getObj("scwin").setReturnValue("info.newValue : " + info.newValue); 
}
